=== PriceCalculator
     1	package hotel.reservations;
     2	
     3	import hotel.rooms.Room;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	import java.time.Month;
     8	
     9	/**
    10	 * The price of a stay, as its rate plan sets it. Most plans start from the seasonal price: every night
    11	 * costs the room's nightly rate, plus the high-season surcharge on high-season nights, and the plan may
    12	 * then give a discount on the sum. Money is rounded to cents (half-even) at every step.
    13	 */
    14	public final class PriceCalculator {
    15	
    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    17	
    18	    public Price calculate(Room room, NewReservation request) {
    19	        return request.ratePlan().price(room, request, this);
    20	    }
    21	
    22	    /** The sum of the nights' prices, less the given share of it as a discount. */
    23	    Price seasonalPrice(Room room, LocalDate checkIn, LocalDate checkOut, BigDecimal discountRate) {
    24	        int nights = 0;
    25	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    26	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    27	            subtotal = subtotal.add(nightPrice(room, night));
    28	            nights++;
    29	        }
    30	        BigDecimal discount = cents(subtotal.multiply(discountRate));
    31	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    32	    }
    33	
    34	    BigDecimal nightPrice(Room room, LocalDate night) {
    35	        BigDecimal nightlyRate = room.nightlyRate();
    36	        if (isHighSeason(night)) {
    37	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    38	        }
    39	        return cents(nightlyRate);
    40	    }
    41	
    42	    /** High season: from December 15 to the end of February, and the whole of July. */
    43	    static boolean isHighSeason(LocalDate date) {
    44	        Month month = date.getMonth();
    45	        return month == Month.JANUARY
    46	                || month == Month.FEBRUARY
    47	                || month == Month.JULY
    48	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    49	    }
    50	
    51	    static BigDecimal cents(BigDecimal value) {
    52	        return value.setScale(2, RoundingMode.HALF_EVEN);
    53	    }
    54	}
